import java.util.*;
import java.util.stream.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);

        if (!sc.hasNextInt()) {
            sc.close();
            return;
        }

        int n = sc.nextInt();
        if (n <= 0) {
            sc.close();
            return;
        }

        List<String> elements = new ArrayList<>();
        sc.nextLine();
        for (int i = 0; i < n; i++) {
            if (sc.hasNextLine()) {
                String line = sc.nextLine().trim();
                if (line.length() == 1 && Character.isDigit(line.charAt(0))) {
                    elements.add(line);
                } else {
                    elements.add(line);
                }
            }
        }
        sc.close();

        if (elements.size() == 0) {
            return;
        }

        String first = elements.get(0);
        boolean isInteger = true;
        try {
            Integer.parseInt(first);
        } catch (NumberFormatException e) {
            isInteger = false;
        }

        if (isInteger) {
            List<Integer> intList = elements.stream()
                .map(Integer::parseInt)
                .collect(Collectors.toList());
            MaxFinder<Integer> finder = new MaxFinder<>();
            Integer max = finder.findMax(intList);
            System.out.println("Maximum: " + max);
        } else {
            boolean isDouble = true;
            try {
                Double.parseDouble(first);
            } catch (NumberFormatException e) {
                isDouble = false;
            }

            if (isDouble) {
                List<Double> doubleList = elements.stream()
                    .map(Double::parseDouble)
                    .collect(Collectors.toList());
                MaxFinder<Double> finder = new MaxFinder<>();
                Double max = finder.findMax(doubleList);
                System.out.println("Maximum: " + max);
            } else {
                MaxFinder<String> finder = new MaxFinder<>();
                String max = finder.findMax(elements);
                System.out.println("Maximum: " + max);
            }
        }
    }
}

class MaxFinder<T extends Comparable<T>> {
    public T findMax(List<T> list) {
        if (list == null || list.size() == 0) {
            return null;
        }

        T max = list.get(0);
        for (int i = 1; i < list.size(); i++) {
            if (list.get(i).compareTo(max) > 0) {
                max = list.get(i);
            }
        }
        return max;
    }
}
